import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.DB9Ll7VW.js";const u=JSON.parse('{"title":"Payments & gateways","description":"Connect PayPal in the free Sikshya plugin, plus the Pro premium gateways — Stripe, Razorpay, Mollie, Paystack, Square, Authorize.Net, and Bank Transfer.","frontmatter":{"title":"Payments & gateways","description":"Connect PayPal in the free Sikshya plugin, plus the Pro premium gateways — Stripe, Razorpay, Mollie, Paystack, Square, Authorize.Net, and Bank Transfer."},"headers":[],"relativePath":"payment-settings.md","filePath":"payment-settings.md","lastUpdated":1778327862000}'),n={name:"payment-settings.md"};function r(i,t,l,p,d,c){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="payments-gateways" tabindex="-1">Payments &amp; gateways <a class="header-anchor" href="#payments-gateways" aria-label="Permalink to &quot;Payments &amp; gateways&quot;">​</a></h1><div class="doc-pro-callout"><span class="doc-pro-pill">Pro</span><span><strong>Stripe &amp; other premium gateways are Sikshya Pro.</strong> The free plugin ships PayPal &amp; Offline. Activate a license under <em>Sikshya → License</em> to unlock the rest.</span><a class="doc-pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing" target="_blank" rel="noopener">View pricing →</a></div><p>Sikshya&#39;s free plugin includes <strong>PayPal</strong> as a fully-working gateway and <strong>Offline / manual</strong> for B2B or invoiced sales. <strong>Stripe is not in the free plugin</strong> — Stripe and the other premium gateways (Razorpay, Mollie, Paystack, Square, Authorize.Net, Bank Transfer) are <strong>Pro-only add-ons</strong> that you turn on under <span class="screen-path">Sikshya → Add-ons</span> after activating a license.</p><h2 id="what-s-included" tabindex="-1">What&#39;s included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s included&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gateway</th><th>Free</th><th>Pro</th><th>Notes</th></tr></thead><tbody><tr><td><strong>PayPal</strong></td><td>✅</td><td>✅</td><td>Simple (email + IPN) and Advanced (REST + webhooks) modes.</td></tr><tr><td><strong>Offline / manual</strong></td><td>✅</td><td>✅</td><td>Bank deposit, Stripe outside Sikshya, B2B invoices. Admin marks orders paid.</td></tr><tr><td><strong>Stripe</strong></td><td>—</td><td>✅</td><td>Pro-only add-on. One-time + recurring (with the Subscriptions add-on).</td></tr><tr><td><strong>Razorpay</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>India: cards, UPI, netbanking, wallets.</td></tr><tr><td><strong>Mollie</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>Europe: iDEAL, Bancontact, SEPA, cards.</td></tr><tr><td><strong>Paystack</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>Africa-first; cards, transfers, mobile money.</td></tr><tr><td><strong>Square</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>North America / UK / AU / JP cards.</td></tr><tr><td><strong>Authorize.Net</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>US-centric cards.</td></tr><tr><td><strong>Bank Transfer</strong></td><td>— <span class="pro-pill">PRO</span></td><td>✅</td><td>Manual settlement, with bank details on the order.</td></tr></tbody></table><h2 id="where-to-configure" tabindex="-1">Where to configure <a class="header-anchor" href="#where-to-configure" aria-label="Permalink to &quot;Where to configure&quot;">​</a></h2><p>Open <span class="screen-path">Sikshya → Settings → Payment</span>.</p><p>The screen has three sections:</p><ol><li><strong>Pricing &amp; taxes</strong> — tax rate (%), &quot;prices include tax&quot;, currency.</li><li><strong>Discounts &amp; coupons</strong> — allow coupons site-wide, max discount, default coupon lifetime.</li><li><strong>Invoicing</strong> — auto-create invoices on success, invoice number prefix.</li></ol><p>Below those is the <strong>Payment gateways</strong> section. Each gateway is a row you can toggle on / off. Pro-gated gateways display a <strong>PRO</strong> badge until you have an active license.</p><p>For each enabled gateway, expand the row to see its specific fields (described below).</p><h2 id="paypal-free" tabindex="-1">PayPal (free) <a class="header-anchor" href="#paypal-free" aria-label="Permalink to &quot;PayPal (free)&quot;">​</a></h2><p>PayPal is the primary free gateway. Two modes:</p><h3 id="simple-mode" tabindex="-1">Simple mode <a class="header-anchor" href="#simple-mode" aria-label="Permalink to &quot;Simple mode&quot;">​</a></h3><p>Easy setup — just an email address.</p><ol class="step-list"><li>Tick <strong>Enable PayPal</strong>.</li><li>Set <strong>Integration mode</strong> to <strong>Simple (email + IPN)</strong>.</li><li>Paste your <strong>PayPal email</strong>.</li><li>Tick <strong>Test mode (sandbox)</strong> until you&#39;ve tested.</li><li>Save.</li></ol><p>The buy button redirects to PayPal. PayPal posts a notification (IPN) back to <code>/wp-json/sikshya/v1/webhooks/paypal-ipn</code>. Sikshya verifies and fulfills the order.</p><h3 id="advanced-rest-mode" tabindex="-1">Advanced (REST) mode <a class="header-anchor" href="#advanced-rest-mode" aria-label="Permalink to &quot;Advanced (REST) mode&quot;">​</a></h3><p>Full webhook support, recurring payments, and better reporting. Requires PayPal developer credentials.</p><ol class="step-list"><li>In your PayPal developer dashboard, create an app and copy the <strong>Client ID</strong> and <strong>Secret</strong>.</li><li>Set up a webhook on the PayPal app pointing to <code>https://yoursite.com/wp-json/sikshya/v1/webhooks/paypal</code>.</li><li>Copy the <strong>Webhook ID</strong>.</li><li>In Sikshya, set <strong>Integration mode</strong> to <strong>Advanced (REST)</strong>, paste the three values.</li><li>Save.</li></ol><h2 id="offline-manual-free" tabindex="-1">Offline / manual (free) <a class="header-anchor" href="#offline-manual-free" aria-label="Permalink to &quot;Offline / manual (free)&quot;">​</a></h2><p>Useful for B2B, invoices, or &quot;wire to our bank account&quot; customers.</p><ol class="step-list"><li>Tick <strong>Enable offline / manual payment</strong>.</li><li>Type the <strong>Offline payment instructions</strong> learners see at checkout (e.g. wire details, contact info).</li><li>Tick <strong>Auto-enroll after offline checkout</strong> if you want learners enrolled immediately, or leave off if you want to verify payment first.</li></ol><p>When a learner picks <strong>Offline</strong> at checkout, Sikshya creates a <strong>Pending</strong> order. Once you&#39;ve received the money:</p><ul><li>Open <span class="screen-path">Commerce → Sales → Orders</span>.</li><li>Click the row → <strong>Mark paid</strong>.</li><li>Choose <strong>Mark paid and enroll now</strong> (the learner gets enrolled and emailed).</li></ul><h2 id="stripe-pro" tabindex="-1">Stripe <span class="pro-pill">PRO</span> <a class="header-anchor" href="#stripe-pro" aria-label="Permalink to &quot;Stripe &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Stripe — cards, wallets, and recurring billing</span></div><p class="pro-callout__desc">Stripe is a <strong>Pro-only</strong> gateway — it isn&#39;t bundled with the free Sikshya plugin. After activating a Pro license and toggling the Stripe add-on under <span class="screen-path">Sikshya → Add-ons</span>, the gateway shows up in <span class="screen-path">Settings → Payment</span>. With Pro you can also pair Stripe with the <strong>Subscriptions</strong> add-on for recurring courses.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Unlock Stripe →</a></div><p>Setup (after activating Pro):</p><ol class="step-list"><li>Tick <strong>Enable Stripe</strong>.</li><li>Paste <strong>Publishable key</strong> and <strong>Secret key</strong> from your Stripe dashboard.</li><li>Create a webhook in Stripe pointing to <code>https://yoursite.com/wp-json/sikshya/v1/webhooks/stripe</code>.</li><li>Copy the webhook signing secret (<code>whsec_...</code>) and paste into <strong>Webhook secret</strong>.</li><li>Tick <strong>Test mode (sandbox)</strong>, save, run a test transaction with card <code>4242 4242 4242 4242</code>.</li><li>Switch to live keys and run one tiny live transaction, then refund it via the Stripe dashboard to verify the full loop.</li></ol><h2 id="razorpay-pro" tabindex="-1">Razorpay <span class="pro-pill">PRO</span> <a class="header-anchor" href="#razorpay-pro" aria-label="Permalink to &quot;Razorpay &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>Popular in India.</p><ul><li><strong>Key ID</strong> + <strong>Key Secret</strong> from the Razorpay dashboard.</li><li>Webhook URL: <code>https://yoursite.com/wp-json/sikshya/v1/webhooks/razorpay</code>.</li><li>Optional <strong>Webhook secret</strong>.</li></ul><h2 id="mollie-pro" tabindex="-1">Mollie <span class="pro-pill">PRO</span> <a class="header-anchor" href="#mollie-pro" aria-label="Permalink to &quot;Mollie &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>Strong in Europe (Netherlands, Belgium, Germany, France).</p><ul><li><strong>API key</strong> (one key for live or test, prefixed <code>live_</code> / <code>test_</code>).</li><li>Optional list of <strong>Payment methods</strong> to offer (iDEAL, Bancontact, etc.).</li><li>Optional <strong>Webhook secret</strong>.</li></ul><h2 id="paystack-pro" tabindex="-1">Paystack <span class="pro-pill">PRO</span> <a class="header-anchor" href="#paystack-pro" aria-label="Permalink to &quot;Paystack &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>Africa-first; supports recurring (works with <strong>Subscriptions</strong> add-on).</p><ul><li><strong>Public key</strong> + <strong>Secret key</strong> from the Paystack dashboard.</li><li>Optional <strong>Payment channels</strong> (e.g. card-only, bank-only).</li><li>Optional <strong>Webhook secret</strong>.</li></ul><h2 id="square-pro" tabindex="-1">Square <span class="pro-pill">PRO</span> <a class="header-anchor" href="#square-pro" aria-label="Permalink to &quot;Square &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>US, UK, Canada, Australia, Japan.</p><ul><li><strong>Application ID</strong>, <strong>Access token</strong>, <strong>Location ID</strong>, <strong>Webhook signature key</strong>.</li><li>Sandbox has its own credentials.</li></ul><h2 id="authorize-net-pro" tabindex="-1">Authorize.Net <span class="pro-pill">PRO</span> <a class="header-anchor" href="#authorize-net-pro" aria-label="Permalink to &quot;Authorize.Net &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>US-centric; popular with established merchants.</p><ul><li><strong>API Login ID</strong>, <strong>Public client key</strong>, <strong>Transaction key</strong>, <strong>Signature key</strong>.</li><li>Sandbox URL: <code>https://sandbox.authorize.net</code>.</li></ul><h2 id="bank-transfer-pro" tabindex="-1">Bank Transfer <span class="pro-pill">PRO</span> <a class="header-anchor" href="#bank-transfer-pro" aria-label="Permalink to &quot;Bank Transfer &lt;span class=&quot;pro-pill&quot;&gt;PRO&lt;/span&gt;&quot;">​</a></h2><p>For accountants who need a real bank reference.</p><p>Fields:</p><ul><li><strong>Bank name</strong>, <strong>Account name</strong>, <strong>Account number</strong>, <strong>Routing / SWIFT</strong>, <strong>Instructions</strong>.</li></ul><p>These details show on the order page. The order is <strong>Pending</strong> until you mark it paid, just like Offline / manual.</p><div class="pro-callout"><div class="pro-callout__head"><span class="pro-callout__badge">PRO</span><span class="pro-callout__title">Six premium gateways + bank transfer</span></div><p class="pro-callout__desc">Razorpay, Mollie, Paystack, Square, Authorize.Net, and Bank Transfer are all part of Sikshya Pro. One license, every gateway you&#39;ll need.</p><a class="pro-callout__cta" href="https://mantrabrain.com/plugins/sikshya/#pricing">Compare Pro plans →</a></div><h2 id="refunds" tabindex="-1">Refunds <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;Refunds&quot;">​</a></h2><p>The order detail page has a <strong>Refund</strong> action. Three patterns:</p><table tabindex="0"><thead><tr><th>Gateway</th><th>Recommended refund flow</th></tr></thead><tbody><tr><td><strong>PayPal / Stripe</strong></td><td>Refund in the gateway dashboard first, then mark refunded in Sikshya.</td></tr><tr><td><strong>Razorpay / Mollie / Paystack / Square / Authorize.Net</strong></td><td>Same — gateway dashboard first, then mark refunded.</td></tr><tr><td><strong>Offline / Bank Transfer</strong></td><td>Refund manually via your bank, then mark refunded.</td></tr></tbody></table><p>When you mark refunded:</p><ul><li>The order status changes to <strong>Refunded</strong>.</li><li>The enrollment is cancelled.</li><li>A refund row is written in your payments table.</li><li>The <code>sikshya_user_unenrolled</code> action fires (so any downstream automation runs).</li></ul><p>The setting <strong>Try to refund automatically when a student leaves</strong> under Enrollment exists but its reliability depends on the gateway adapter. Treat it as a convenience, not a guarantee.</p><h2 id="test-mode-workflow" tabindex="-1">Test mode workflow <a class="header-anchor" href="#test-mode-workflow" aria-label="Permalink to &quot;Test mode workflow&quot;">​</a></h2><p>A safe way to test any gateway:</p><ol class="step-list"><li>Toggle <strong>Test mode (sandbox)</strong> on for the gateway.</li><li>Paste sandbox / test keys.</li><li>Set up the gateway webhook in <em>sandbox</em> mode pointing to your <strong>staging</strong> URL — never live URL with test keys, never live keys with localhost.</li><li>Buy a course as a fresh test learner with the gateway&#39;s test card or sandbox account.</li><li>Verify: order shows <strong>Paid</strong>, learner shows under <strong>Enrollments</strong>, the receipt email arrives.</li><li>Switch to <strong>Live</strong> mode, paste live keys, change the webhook to live mode, and run one small live transaction with a real card. Refund it via the gateway dashboard.</li></ol><h2 id="currency" tabindex="-1">Currency <a class="header-anchor" href="#currency" aria-label="Permalink to &quot;Currency&quot;">​</a></h2><p>Set under <span class="screen-path">Settings → General</span>:</p><ul><li><strong>Currency</strong> — code (USD, EUR, INR, NPR, …).</li><li><strong>Currency position</strong> — <code>$199</code>, <code>199$</code>, <code>$ 199</code>, or <code>199 $</code>.</li><li><strong>Thousand separator</strong> — <code>,</code> or <code>.</code> or space.</li><li><strong>Decimal separator</strong> — <code>.</code> or <code>,</code>.</li><li><strong>Number of decimals</strong> — usually 2 (or 0 for JPY).</li></ul><blockquote><p>Sikshya stores prices as floats. For very high transaction volume, ask your developer about high-precision migrations.</p></blockquote><h2 id="webhook-urls-cheat-sheet" tabindex="-1">Webhook URLs (cheat sheet) <a class="header-anchor" href="#webhook-urls-cheat-sheet" aria-label="Permalink to &quot;Webhook URLs (cheat sheet)&quot;">​</a></h2><p>Copy these into the corresponding gateway dashboard:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/paypal</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/paypal-ipn</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/stripe</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/razorpay</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/mollie</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/paystack</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/square</span></span>
<span class="line"><span>https://yoursite.com/wp-json/sikshya/v1/webhooks/authorize-net</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/docs/email-settings">Email &amp; notifications</a> — the receipts and welcome emails that fire after payment.</li><li><a href="/docs/third-party-integrations">Pro add-ons</a> — every Pro feature, including subscriptions.</li><li><a href="/docs/troubleshooting">Troubleshooting</a> — what to do when payments don&#39;t show up.</li></ul>`,68)])])}const g=e(n,[["render",r]]);export{u as __pageData,g as default};
